flatString = ''.join([x for row in screenArray for x in row])

def selective_rle_encode(s):
    out = []
    i = 0
    n = len(s)

    while i < n:
        c = s[i]
        if c in (' ', '_','~'):
            j = i
            while j < n and s[j] == c:j += 1
            count = j - i
            out.append(f'{{{c}{count}}}')
            i = j
        else:
            out.append(c)
            i += 1
    return ''.join(out)

def selective_rle_decode(s):
    out = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '{':
            char = s[i + 1]
            j = i + 2
            while s[j] != '}':j += 1
            count = int(s[i + 2:j])
            out.append(char * count)
            i = j + 1
        else:
            out.append(s[i])
            i += 1

    return ''.join(out)

encoded = selective_rle_encode(flatString)
decoded = selective_rle_decode(encoded)

print(flatString)
print('')
print(encoded)
print('')
print(decoded)
